param(
    [string]$ProjectPath = (Get-Location).Path
)

$ErrorActionPreference = "Stop"

$ProjectPath = (Resolve-Path $ProjectPath).Path
$GamePath = Join-Path $ProjectPath "game"

if (-not (Test-Path $GamePath)) {
    Write-Host ""
    Write-Host "ERROR: No encuentro la carpeta 'game' en:" -ForegroundColor Red
    Write-Host "  $ProjectPath" -ForegroundColor Yellow
    Write-Host ""
    Write-Host "Ejecuta este script desde la carpeta raiz del proyecto Ren'Py." -ForegroundColor Yellow
    exit 1
}

$stamp = Get-Date -Format "yyyyMMdd_HHmmss"
$BackupPath = Join-Path $ProjectPath ("backup_before_v030_" + $stamp)
New-Item -ItemType Directory -Path $BackupPath -Force | Out-Null

Write-Host ""
Write-Host "==============================================" -ForegroundColor Cyan
Write-Host " NIGHTFALL VILLAGE - UPGRADE v0.3.0" -ForegroundColor Cyan
Write-Host "==============================================" -ForegroundColor Cyan
Write-Host ""
Write-Host "Proyecto: $ProjectPath"
Write-Host "Backup:   $BackupPath"
Write-Host ""

Get-ChildItem $GamePath -Filter "*.rpy" -File -ErrorAction SilentlyContinue | ForEach-Object {
    Copy-Item $_.FullName (Join-Path $BackupPath $_.Name) -Force
}

if (Test-Path (Join-Path $ProjectPath "README.md")) {
    Copy-Item (Join-Path $ProjectPath "README.md") (Join-Path $BackupPath "README.md") -Force
}

$OldUi = Join-Path $GamePath "hos_ui.rpy"
if (Test-Path $OldUi) {
    Copy-Item $OldUi (Join-Path $BackupPath "hos_ui.rpy") -Force
    Remove-Item $OldUi -Force
}

function Write-EmbeddedFile {
    param(
        [string]$RelativePath,
        [string]$Base64
    )

    $Target = Join-Path $ProjectPath $RelativePath
    $Dir = Split-Path $Target -Parent
    New-Item -ItemType Directory -Path $Dir -Force | Out-Null
    [System.IO.File]::WriteAllBytes(
        $Target,
        [System.Convert]::FromBase64String($Base64)
    )
    Write-Host ("  OK  " + $RelativePath) -ForegroundColor Green
}

Write-Host "Instalando el build..." -ForegroundColor White

Write-EmbeddedFile -RelativePath "README.md" -Base64 ""
Write-EmbeddedFile -RelativePath "game\\events.rpy" -Base64 ""
Write-EmbeddedFile -RelativePath "game\\gui.rpy" -Base64 ""
Write-EmbeddedFile -RelativePath "game\\images\\ui\\archive_bg.png" -Base64 ""
Write-EmbeddedFile -RelativePath "game\\images\\ui\\aya_house_bg.png" -Base64 ""
Write-EmbeddedFile -RelativePath "game\\images\\ui\\home_bg.png" -Base64 ""
Write-EmbeddedFile -RelativePath "game\\images\\ui\\main_menu_bg.png" -Base64 ""
Write-EmbeddedFile -RelativePath "game\\images\\ui\\map_bg.png" -Base64 ""
Write-EmbeddedFile -RelativePath "game\\images\\ui\\market_bg.png" -Base64 ""
Write-EmbeddedFile -RelativePath "game\\images\\ui\\old_shrine_bg.png" -Base64 ""
Write-EmbeddedFile -RelativePath "game\\images\\ui\\riverside_bg.png" -Base64 ""
Write-EmbeddedFile -RelativePath "game\\images\\ui\\square_bg.png" -Base64 ""
Write-EmbeddedFile -RelativePath "game\\images\\ui\\training_bg.png" -Base64 ""
Write-EmbeddedFile -RelativePath "game\\options.rpy" -Base64 ""
Write-EmbeddedFile -RelativePath "game\\screens.rpy" -Base64 ""
Write-EmbeddedFile -RelativePath "game\\script.rpy" -Base64 ""
Write-EmbeddedFile -RelativePath "game\\systems.rpy" -Base64 ""
Write-EmbeddedFile -RelativePath "game\\visuals.rpy" -Base64 ""

Get-ChildItem $GamePath -Filter "*.rpyc" -File -ErrorAction SilentlyContinue |
    Remove-Item -Force -ErrorAction SilentlyContinue

Write-Host ""
Write-Host "==============================================" -ForegroundColor Green
Write-Host " UPGRADE COMPLETADO" -ForegroundColor Green
Write-Host "==============================================" -ForegroundColor Green
Write-Host ""
Write-Host "Incluye:"
Write-Host "  - Menu principal cinematografico"
Write-Host "  - Fondos originales generados para cada zona"
Write-Host "  - Dialogos anclados abajo"
Write-Host "  - Mapa visual con 8 ubicaciones"
Write-Host "  - Morning / Afternoon / Evening / Night"
Write-Host "  - Love / Hatred y requisitos de relaciones"
Write-Host "  - Horarios de NPC"
Write-Host "  - Interactive Guide"
Write-Host "  - Event Log"
Write-Host "  - Night Trader + objetos secretos"
Write-Host "  - Ubicaciones desbloqueables"
Write-Host "  - Save / Load / Settings personalizados"
Write-Host "  - Developer Tools + Event Inspector (F2)"
Write-Host ""
Write-Host "Abre Ren'Py Launcher y pulsa Launch Project." -ForegroundColor Yellow
Write-Host "Si Ren'Py muestra un error, copia el bloque completo y enviamelo." -ForegroundColor Yellow
Write-Host ""
